package dev.cubicchunks.worldgen;

import java.util.ArrayList;
import java.util.List;

import com.mojang.serialization.Codec;

import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;

/**
 * Chunk-attached record of which sections of a column were generated by this mod.
 *
 * <p>The extension cubes are installed into ordinary vanilla {@code LevelChunk}s, so the world
 * format is unchanged; remembering which 16-block slices came from the extension generator is what
 * keeps them from being re-noised (and therefore overwritten) on the next session. It is stored as
 * a chunk data attachment, which the chunk serializer writes and restores with the chunk itself.
 *
 * <p>Bit {@code i} stands for section index {@code i}, counted from the column's lowest section.
 */
public final class GeneratedSectionsData implements ValueIOSerializable {

    private static final String KEY = "cubic_generated_sections";
    private static final long[] EMPTY = new long[0];

    private static final Codec<long[]> BITS_CODEC = Codec.LONG.listOf().xmap(
            list -> {
                long[] array = new long[list.size()];
                for (int i = 0; i < array.length; i++) {
                    array[i] = list.get(i);
                }
                return array;
            },
            array -> {
                List<Long> list = new ArrayList<>(array.length);
                for (long value : array) {
                    list.add(value);
                }
                return list;
            });

    private long[] bits = EMPTY;

    public long[] bits() {
        return this.bits;
    }

    public void setBits(long[] bits) {
        this.bits = bits == null ? EMPTY : bits;
    }

    @Override
    public void serialize(ValueOutput output) {
        if (this.bits.length > 0) {
            output.store(KEY, BITS_CODEC, this.bits);
        }
    }

    @Override
    public void deserialize(ValueInput input) {
        this.bits = input.read(KEY, BITS_CODEC).orElse(EMPTY);
    }
}
